const ATTRIBUTION = Symbol("search-hit-attribution");
export function attachSearchHitAttribution(target, attribution) {
    const host = target;
    host[ATTRIBUTION] = {
        ...host[ATTRIBUTION],
        ...attribution,
    };
}
export function copySearchHitAttribution(from, to, outputDescription) {
    const memoryInference = from[ATTRIBUTION]?.memoryInference;
    if (!memoryInference)
        return;
    if (memoryInference.exposure !== "surface") {
        attachSearchHitAttribution(to, { memoryInference });
    }
    else if (memoryInference.surfaceFields?.includes("description") &&
        memoryInference.surfaceDescription !== undefined &&
        memoryInference.surfaceDescription === outputDescription) {
        // Curate emits descriptions, not tags. Carry only the field it retained.
        attachSearchHitAttribution(to, { memoryInference: { ...memoryInference, surfaceFields: ["description"] } });
    }
}
export function getSearchHitAttribution(target) {
    return target[ATTRIBUTION];
}
export function buildUsageEventAttribution(attribution, entryRef, projection = "full") {
    const memoryInference = attribution?.memoryInference;
    if (!memoryInference)
        return undefined;
    const childRef = memoryInference.exposure === "direct" ? entryRef : memoryInference.childRef;
    const surfaceFields = memoryInference.surfaceFields ?? [];
    const surfaceVisible = memoryInference.exposure !== "surface" ||
        (projection === "full"
            ? surfaceFields.length > 0
            : projection === "normal" || projection === "agent"
                ? surfaceFields.includes("description")
                : false);
    if (childRef?.includes("//") !== true || !surfaceVisible)
        return undefined;
    return { memoryInference: { exposure: memoryInference.exposure, childRef } };
}
export function usageEventAttributionMetadata(attribution, entryRef, projection = "full") {
    const applicable = buildUsageEventAttribution(attribution, entryRef, projection);
    return JSON.stringify({
        downstreamAttribution: {
            version: 1,
            control: applicable === undefined,
            ...applicable,
        },
    });
}
